package com.reqlens.app;
import android.app.*;import android.graphics.Typeface;import android.os.Bundle;import android.widget.*;import java.util.*;
public final class ProjectCompareActivity extends Activity{
 private Spinner a,b;private TextView out;private List<ProjectRepository.Project>projects;
 @Override public void onCreate(Bundle x){super.onCreate(x);ProjectRepository.init(this);BrowserHistoryRepository.init(this);ProxyHistoryRepository.init(this);projects=ProjectRepository.snapshot();LinearLayout r=new LinearLayout(this);r.setOrientation(LinearLayout.VERTICAL);r.setPadding(16,16,16,16);TextView t=new TextView(this);t.setText("Project Comparison");t.setTextSize(22);t.setTypeface(Typeface.DEFAULT_BOLD);r.addView(t);a=new Spinner(this);b=new Spinner(this);ArrayAdapter<ProjectRepository.Project>ad=new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,projects);a.setAdapter(ad);b.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,projects));r.addView(a);r.addView(b);Button c=new Button(this);c.setText("COMPARE");c.setOnClickListener(v->compare());r.addView(c);out=new TextView(this);out.setTypeface(Typeface.MONOSPACE);out.setTextIsSelectable(true);r.addView(out);setContentView(r);}
 private void compare(){if(projects.isEmpty())return;ProjectRepository.Project x=(ProjectRepository.Project)a.getSelectedItem(),y=(ProjectRepository.Project)b.getSelectedItem();out.setText(stats(x.id,x.name)+"\n\n"+stats(y.id,y.name));}
 private String stats(long id,String name){int proxy=0,browser=0,errors=0;long bytes=0;Set<String>hosts=new HashSet<>();for(ProxyEvent e:ProxyHistoryRepository.snapshotAll())if(e.projectId==id||e.projectId==0&&id==1){proxy++;if(!e.host.isEmpty())hosts.add(e.host);if(e.status>=400)errors++;bytes+=Math.max(0,e.bytes);}for(BrowserRequest r:BrowserHistoryRepository.snapshotAll())if(r.projectId==id||r.projectId==0&&id==1)browser++;return name+"\nproxy="+proxy+" browser="+browser+" hosts="+hosts.size()+" errors="+errors+" bytes="+bytes;}
}
